SourceCode.Declaration:
/// <summary>
/// Data contract for the MET Transfer Order Received business event.
/// Contains the data area and transfer order ID relevant to the event.
/// </summary>
public class METTransferOrderReceivedBusinessEventsContract extends BusinessEventsContract
{
    DataAreaId          dataAreaId;
    InventTransferId    transferId;

}

Method.Source:
/// <summary>
/// Constructs a <c>METTransferOrderReceivedBusinessEventsContract</c>.
/// </summary>
/// <param name = "_transferTable">The <c>InventTransferTable</c> record.</param>
/// <returns>An instance of <c>METTransferOrderReceivedBusinessEventsContract</c>.</returns>
public static METTransferOrderReceivedBusinessEventsContract newFromInventTransferTable(InventTransferTable _transferTable)
{
    var contract = new METTransferOrderReceivedBusinessEventsContract();
    contract.initialize(_transferTable);
    return contract;
}

/// <summary>
/// Gets or sets the data area ID associated with the transfer order event.
/// </summary>
/// <param name="_dataAreaId">The data area ID to set. If not provided, returns the current value.</param>
/// <returns>The current data area ID.</returns>
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Gets or sets the transfer order ID for the business event.
/// </summary>
/// <param name="_transferId">The transfer order ID to set. If not provided, returns the current value.</param>
/// <returns>The current transfer order ID.</returns>
public InventTransferId parmTransferId(InventTransferId _transferId = transferId)
{
    transferId = _transferId;
    return transferId;
}

/// <summary>
/// Initializes the contract with values from the transfer order table.
/// </summary>
/// <param name="_transferTable">The transfer order table record.</param>
/// <returns>METTransferOrderReceivedBusinessEventsContract</returns>
public void initialize(InventTransferTable _transferTable)
{
    transferId = _transferTable.TransferId;
    dataAreaId = CompanyInfo::find().DataArea;
}
